<script>$(function(){const form=$('#crm-report-filter'),out=$('#report-output'),team=$('#report-team'),owner=$('#report-owner'),url=@json(route('crm.reports.data')),index=@json(route('crm.reports.index'));let report=new URL(location.href).searchParams.get('tab')||'pipeline',request;const money=n=>n===null||n===undefined?'-':Number(n).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});window.erpInitSelect2(owner,{theme:'bootstrap-5',allowClear:true,placeholder:'ทุกคนที่มีสิทธิ์',ajax:{url:@json(route('crm.forecast.owner-options')),dataType:'json',delay:250,data:p=>({q:p.term||'',page:p.page||1,team_id:team.val()||''}),processResults:d=>d}});team.on('change',()=>owner.val(null).trigger('change'));function esc(v){return $('<div>').text(v??'').html();}function card(label,value){return '<div class="col-6 col-xl-3"><div class="card h-100"><div class="card-body"><small class="text-secondary">'+esc(label)+'</small><strong class="d-block fs-5 mt-2">'+esc(value)+'</strong></div></div></div>';}function table(rows,headers,values){if(!rows.length)return '<div class="text-center text-secondary py-4">ไม่พบข้อมูลในเดือนนี้</div>';return '<div class="table-responsive"><table class="table align-middle"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+values(r).map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}function render(d){const x=d.data,s=d.report==='sales'?x.summary:x.summary||{};let html='<div class="row g-3 mb-4">';if(d.report==='sales')html+=card('Pipeline',money(s.pipeline))+card('Weighted Forecast',money(s.forecast))+card('ยอดขายจริง',money(s.actual))+card('Forecast Gap',money(s.gap));if(d.report==='pipeline')html+=card('Opportunity เปิด',s.count)+card('Pipeline Value',money(s.pipeline))+card('Weighted Forecast',money(s.forecast))+card('ดีลเสี่ยง',s.risk);if(d.report==='activities')html+=card('Planned',s.planned)+card('Completed',s.completed)+card('Overdue',s.overdue)+card('Completion Rate',s.completion_rate===null?'-':s.completion_rate+'%');if(d.report==='losses')html+=card('จำนวน LOST',s.count)+card('Lost Value',money(s.value))+card('ไม่ระบุเหตุผล',s.unknown);html+='</div><div class="card"><div class="card-body p-3 p-lg-4"><h2 class="h5 mb-3">'+({pipeline:'Pipeline ตาม Stage',sales:'Target / Actual / Forecast รายพนักงาน',activities:'กิจกรรมตามประเภท',losses:'Lost Reason'}[d.report])+'</h2>';if(d.report==='sales')html+=table(x.rows,['พนักงาน','Opportunity','Pipeline','Forecast','Actual','Target','Gap'],r=>[r.label,r.opportunity_count,money(r.pipeline),money(r.forecast),money(r.actual),r.target===null?'ยังไม่กำหนด':money(r.target),r.gap===null?'-':money(r.gap)]);else if(d.report==='activities')html+=table(x.rows,['ประเภท','Planned','Completed','Overdue'],r=>[r.label,r.planned,r.completed,r.overdue]);else html+=table(x.rows,['รายการ','จำนวน','มูลค่า','Forecast'],r=>[r.label,r.count,money(r.value??r.pipeline),money(r.forecast)]);html+='</div></div>';if(d.report==='sales'&&x.performance)html+='<div class="card mt-3"><div class="card-body"><h2 class="h5">Conversion และระยะเวลาขาย</h2><div class="row g-3">'+card('Opportunity ใหม่',x.performance.created)+card('Won',x.performance.won)+card('Lost',x.performance.lost)+card('Win Rate',x.performance.win_rate===null?'-':Number(x.performance.win_rate).toFixed(1)+'%')+'</div></div></div>';out.html(html).attr('aria-busy','false');}function load(push){if(request)request.abort();const p=new URLSearchParams(new FormData(form[0]));p.set('report',report);$('#report-export').attr('href',@json(route('crm.reports.export'))+'?'+p.toString());out.attr('aria-busy','true').html('<div class="card"><div class="card-body text-center text-secondary py-5">กำลังโหลดรายงาน...</div></div>');request=$.getJSON(url,p.toString()).done(d=>{render(d);$('.nav-link[data-report-tab]').removeClass('active').filter('[data-report-tab="'+report+'"]').addClass('active');if(push)history.pushState({},'',index+'?tab='+report+'&'+p.toString().replace('report='+report+'&',''));}).fail((_,status)=>{if(status!=='abort')out.html('<div class="alert alert-danger">โหลดรายงานไม่สำเร็จ <button class="btn btn-sm btn-outline-danger js-retry" type="button">ลองใหม่</button></div>');});}form.on('submit',e=>{e.preventDefault();load(true);});$('.nav-link[data-report-tab]').on('click',function(){report=$(this).data('report-tab');load(true);});out.on('click','.js-retry',()=>load(false));addEventListener('popstate',()=>location.reload());load(false);});</script>
